from pathlib import Path
import json
from project import output_args
base=output_args('Build an offline needle replay from decoded DST data.')
data=(base/'replay_data.json').read_text(encoding='utf-8')
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bulldogs · DST 逐针回放</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f5f5;color:#153647;font:15px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1300px;margin:auto;padding:34px}h1{font-size:34px;margin:8px 0}.eyebrow{font-size:12px;letter-spacing:2px;color:#5c737d}.subtitle{color:#5c737d;line-height:1.7}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.stat{padding:16px 22px;background:white;border:1px solid #dae3e4;border-radius:12px;min-width:160px}.stat b{display:block;font-size:24px;margin-bottom:5px}.stat span{color:#627982;font-size:12px}.panel{background:white;border:1px solid #dae3e4;border-radius:16px;overflow:hidden}canvas{width:100%;height:460px;display:block}.controls{padding:20px;border-top:1px solid #e5eaea}button,select{border:1px solid #c7d5d8;background:#fff;color:#214757;border-radius:7px;padding:9px 14px;font:inherit;cursor:pointer}button.primary{background:#164c60;color:white;border-color:#164c60}input[type=range]{width:100%;accent-color:#164c60;margin:15px 0}label{margin-right:15px;font-size:13px}.row{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.row span{margin-left:auto;font-variant-numeric:tabular-nums}aside{line-height:1.8;padding:20px 0;color:#57717b}a{color:#1b627e}.legend{font-size:13px;color:#627982;margin-bottom:12px}.orange{color:#c4752b}.pink{color:#ad3c6e}@media(max-width:600px){main{padding:18px}canvas{height:330px}h1{font-size:28px}}</style>
<main><div class="eyebrow">CHENILLE / FIRST VERIFIED PILOT</div><h1>Bulldogs <span style="font-weight:400;color:#738b94">/ Font2</span></h1><div class="subtitle">案例 Bulldogs / Font2 · 基于输出 DST 回读坐标<br>历史人工笔顺复用与曲线重建试验；尚未经过 Wilcom 或实机试绣。</div><div class="stats" id="stats"></div><div class="legend">蓝色：主路径　<span class="orange">橙色：起针回线</span>　<span class="pink">紫红：收针回线</span>　红点：当前针位</div><div class="panel"><canvas id="cv"></canvas><div class="controls"><div class="row"><button class="primary" id="play">播放</button><button id="prev">上一针</button><button id="next">下一针</button><button id="reset">从头</button><select id="view"><option value="all">整词</option><option value="start">起针放大</option><option value="end">收针放大</option></select><select id="speed"><option value="20">20 针/秒</option><option value="80" selected>80 针/秒</option><option value="200">200 针/秒</option></select><span id="counter"></span></div><input id="seek" aria-label="针序" type="range" min="1"><div class="row"><label><input id="ghost" type="checkbox" checked> 显示完整路径</label><label><input id="dots" type="checkbox" checked> 显示落针点</label><span id="pos"></span></div></div></div><aside id="notes"></aside><p><a id="dstlink" href="Bulldogs_F2_330mm.DST" download>下载 DST</a> · <a href="validation.json">验证数据</a> · <a href="stitches.csv">逐针坐标 CSV</a> · <a href="details.png">关键细节图</a></p></main>
<script>const DATA=__DATA__;const p=DATA.points,r=DATA.report;const $=id=>document.getElementById(id),c=$('cv'),ctx=c.getContext('2d');let n=p.length,playing=false,last=0,carry=0;const se=r.return_needle_ranges_1based.start[1],es=r.return_needle_ranges_1based.end[0];$('dstlink').href='Bulldogs_F2_'+r.width_mm+'mm.DST';$('seek').max=p.length;$('seek').value=n;$('stats').innerHTML=[[r.width_mm+' × '+r.height_mm,'实际针迹尺寸 / mm'],[r.stitch_commands,'普通落针命令'],[r.jump_commands,'跳针命令'],[r.return_lengths_mm.start.toFixed(3)+' / '+r.return_lengths_mm.end.toFixed(3),'起 / 收回线弧长 / mm']].map(x=>`<div class="stat"><b>${x[0]}</b><span>${x[1]}</span></div>`).join('');$('notes').textContent='回线按最终量化后的针迹折线累计测量，包含圆弧掉头。两端半径分别为 0.35 / 0.25 mm。保留人工内部回走和原有尖转；本次没有跳转。短针与回走重叠的实物效果需要试绣确认。键盘左右箭头可逐针查看。';
function paint(){const dpr=devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let chosen=$('view').value==='start'?p.slice(0,se+10):$('view').value==='end'?p.slice(es-11):p;let xs=chosen.map(x=>x[0]),ys=chosen.map(x=>x[1]);const lo=[Math.min(...xs),Math.min(...ys)],hi=[Math.max(...xs),Math.max(...ys)];const scale=Math.min((w-80)/(hi[0]-lo[0]+1),(h-70)/(hi[1]-lo[1]+1));const offset=[w/2-(lo[0]+hi[0])/2*scale,h/2-(lo[1]+hi[1])/2*scale];function pt(a){return[a[0]*scale+offset[0],a[1]*scale+offset[1]]}function line(end,color,width){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();p.slice(0,end).forEach((a,i)=>{const b=pt(a);i?ctx.lineTo(...b):ctx.moveTo(...b)});ctx.stroke()}if($('ghost').checked)line(p.length,'#e3e9eb',1);line(n,'#214f68',1.6);for(const [a,b,col] of [[0,se,'#c4752b'],[es-1,p.length,'#ad3c6e']]){ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();p.slice(a,Math.min(b,n)).forEach((v,i)=>{const z=pt(v);i?ctx.lineTo(...z):ctx.moveTo(...z)});ctx.stroke()}if($('dots').checked){ctx.fillStyle='#315b70';p.slice(0,n).forEach(a=>{const b=pt(a);ctx.beginPath();ctx.arc(...b,$('view').value==='all'?1.4:2.6,0,Math.PI*2);ctx.fill()})}const here=pt(p[n-1]);ctx.beginPath();ctx.fillStyle='#e34a3d';ctx.arc(...here,5,0,Math.PI*2);ctx.fill();$('counter').textContent=`${n} / ${p.length} 针`;$('pos').textContent=`X ${p[n-1][0].toFixed(1)} · Y ${p[n-1][1].toFixed(1)} mm`;$('seek').value=n;}
function pause(){playing=false;$('play').textContent='播放'}$('play').onclick=()=>{playing=!playing;if(playing&&n===p.length)n=1;$('play').textContent=playing?'暂停':'播放';last=performance.now();carry=0;paint()};$('seek').oninput=()=>{pause();n=+$('seek').value;paint()};$('prev').onclick=()=>{pause();n=Math.max(1,n-1);paint()};$('next').onclick=()=>{pause();n=Math.min(p.length,n+1);paint()};$('reset').onclick=()=>{pause();n=1;paint()};['view','ghost','dots'].forEach(id=>$(id).onchange=paint);window.onresize=paint;document.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();$(e.key==='ArrowRight'?'next':'prev').click()}};function tick(t){if(playing){carry+=(t-last)/1000*+$('speed').value;let k=Math.floor(carry);carry-=k;if(k){n=Math.min(p.length,n+k);paint()}if(n===p.length)pause()}last=t;requestAnimationFrame(tick)}paint();requestAnimationFrame(tick);</script></html>'''
(base/'replay.html').write_text(html.replace('__DATA__',data),encoding='utf-8')
